        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug is caused by incorrectly calculating the length of the `scope_id` buffer, leading to a potential buffer overflow when the NUL terminator is placed beyond the allocated memory. Specifically, using `sizeof(scope_id)` instead of `sizeof(scope_id) - 1` allows for writing one extra byte, which can corrupt memory and cause undefined behavior.

        Commit message:
        net: off by one in inet6_pton()

If "scope_len" is sizeof(scope_id) then we would put the NUL terminator
one space beyond the end of the buffer.

Fixes: b1a951fe469e ("net/utils: generic inet_pton_with_scope helper")
Signed-off-by: Dan Carpenter <dan.carpenter@oracle.com>
Signed-off-by: Jens Axboe <axboe@fb.com>  

        Patch:

 static int inet6_pton(struct net *net, const char *src, u16 port_num,
 		struct sockaddr_storage *addr)
 {
 	struct sockaddr_in6 *addr6 = (struct sockaddr_in6 *)addr;
 	const char *scope_delim;
 	int srclen = strlen(src);

 	if (srclen > INET6_ADDRSTRLEN)
 		return -EINVAL;

 	if (in6_pton(src, srclen, (u8 *)&addr6->sin6_addr.s6_addr,
 		     '%', &scope_delim) == 0)
 		return -EINVAL;

 	if (ipv6_addr_type(&addr6->sin6_addr) & IPV6_ADDR_LINKLOCAL &&
 	    src + srclen != scope_delim && *scope_delim == '%') {
 		struct net_device *dev;
 		char scope_id[16];
-		size_t scope_len = min_t(size_t, sizeof(scope_id),
+		size_t scope_len = min_t(size_t, sizeof(scope_id) - 1,
 					 src + srclen - scope_delim - 1);

 		memcpy(scope_id, scope_delim + 1, scope_len);
 		scope_id[scope_len] = '\0';

 		dev = dev_get_by_name(net, scope_id);
 		if (dev) {
 			addr6->sin6_scope_id = dev->ifindex;
 			dev_put(dev);
 		} else if (kstrtouint(scope_id, 0, &addr6->sin6_scope_id)) {
 			return -EINVAL;
 		}
 	}

 	addr6->sin6_family = AF_INET6;
 	addr6->sin6_port = htons(port_num);

 	return 0;
 }



